import { StringColumn } from '@servicenow/sdk/core'
import { Flow, wfa, action, FlowObject } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['flow_label_cache_nested'],
        name: 'Flow Label Cache - Nested Objects',
        description: 'Tests label cache with nested complex objects',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            employee: FlowObject({
                label: 'Employee',
                fields: {
                    email: StringColumn({
                        mandatory: true,
                        label: 'Email Address',
                        max_length: 100,
                    }),
                    phone: StringColumn({
                        mandatory: false,
                        label: 'Phone Number',
                        max_length: 20,
                    }),
                    department: StringColumn({
                        mandatory: true,
                        label: 'Department',
                        max_length: 50,
                    }),
                },
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['label_cache_nested_trigger'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['nested_action_step1'] },
            {
                log_message: `Employee: ${wfa.dataPill(params.flowVariables.employee.email, 'string')}, Department: ${wfa.dataPill(params.flowVariables.employee.department, 'string')}`,
                log_level: 'info',
            }
        )
    }
)
